from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, expire_time]
    results = []

    def purge_expired(t):
        expired_keys = [k for k, v in cache.items() if v[1] <= t]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        kind = op[0]
        t = op[1]
        purge_expired(t)

        if kind == 'put':
            key = op[2]
            value = op[3]
            expire = t + ttl
            if key in cache:
                cache[key] = [value, expire]
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, expire]
        elif kind == 'get':
            key = op[2]
            if key in cache:
                val = cache[key][0]
                cache.move_to_end(key)
                results.append(val)
            else:
                results.append(-1)

    return results

